import { LogicWrapper, MakeLogicType, actions, afterMount, connect, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { NodeKind } from '~/queries/schema/schema-general'

import { visionScannersEstimateCreate } from '../generated/api'
import type { EstimateResponseApi } from '../generated/api.schemas'
import { DEFAULT_MODEL } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface highlightPicksVolumeLogicValues {
    currentTeamId: number | null // teamLogic
    cachedSnapshot: VolumeSnapshot | null
    noRecordings: boolean
    volumeEstimate: EstimateResponseApi | null
    volumeEstimateLoading: boolean
    volumeSnapshot: VolumeSnapshot | null
    volumeSnapshotLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface highlightPicksVolumeLogicActions {
    loadVolumeEstimate: () => {
        value: true
    }
    loadVolumeEstimateFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadVolumeEstimateSuccess: (
        volumeSnapshot: VolumeSnapshot | null,
        payload?: {
            value: true
        }
    ) => {
        volumeSnapshot: VolumeSnapshot | null
        payload?: {
            value: true
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface highlightPicksVolumeLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        volumeEstimate: (
            volumeSnapshot: VolumeSnapshot | null,
            currentTeamId: number | null
        ) => EstimateResponseApi | null
        volumeEstimateLoading: (volumeSnapshotLoading: boolean) => boolean
        noRecordings: (volumeEstimate: EstimateResponseApi | null) => boolean
    }
}

export type highlightPicksVolumeLogicType = MakeLogicType<
    highlightPicksVolumeLogicValues,
    highlightPicksVolumeLogicActions,
    Record<string, any>,
    highlightPicksVolumeLogicMeta
>

const ESTIMATE_TTL_MS = 6 * 60 * 60 * 1000
const EMPTY_ESTIMATE_TTL_MS = 10 * 60 * 1000

export interface VolumeSnapshot {
    teamId: number
    estimate: EstimateResponseApi
    fetchedAt: number
}

function freshSnapshot(snapshot: VolumeSnapshot | null, teamId: number | null): VolumeSnapshot | null {
    if (!snapshot || snapshot.teamId !== teamId) {
        return null
    }
    const ttl = snapshot.estimate.matched_sessions_in_window > 0 ? ESTIMATE_TTL_MS : EMPTY_ESTIMATE_TTL_MS
    return Date.now() - snapshot.fetchedAt < ttl ? snapshot : null
}

export const highlightPicksVolumeLogic: LogicWrapper<highlightPicksVolumeLogicType> =
    kea<highlightPicksVolumeLogicType>([
        path(['products', 'replay_vision', 'frontend', 'replay_scanners', 'highlightPicksVolumeLogic']),

        connect(() => ({
            values: [teamLogic, ['currentTeamId']],
        })),

        actions({
            loadVolumeEstimate: true,
        }),

        loaders(({ values }) => ({
            volumeSnapshot: [
                null as VolumeSnapshot | null,
                {
                    loadVolumeEstimate: async (_, breakpoint) => {
                        const teamId = values.currentTeamId
                        if (!teamId) {
                            return null
                        }
                        let estimate: EstimateResponseApi | null = null
                        try {
                            estimate = await visionScannersEstimateCreate(String(teamId), {
                                query: { kind: NodeKind.RecordingsQuery },
                                sampling_rate: 1,
                                model: DEFAULT_MODEL,
                            })
                        } catch {
                            estimate = null
                        }
                        breakpoint()
                        if (!estimate) {
                            return values.cachedSnapshot?.teamId === teamId ? values.cachedSnapshot : null
                        }
                        return { teamId, estimate, fetchedAt: Date.now() }
                    },
                },
            ],
        })),

        reducers({
            cachedSnapshot: [
                null as VolumeSnapshot | null,
                { persist: true, storageKey: 'replay-vision.highlight-picks-volume.snapshot' },
                {
                    loadVolumeEstimateSuccess: (state, { volumeSnapshot }) => volumeSnapshot ?? state,
                },
            ],
        }),

        selectors({
            volumeEstimate: [
                (s) => [s.volumeSnapshot, s.currentTeamId],
                (snapshot: VolumeSnapshot | null, teamId: number | null): EstimateResponseApi | null =>
                    snapshot && snapshot.teamId === teamId ? snapshot.estimate : null,
            ],
            volumeEstimateLoading: [(s) => [s.volumeSnapshotLoading], (loading: boolean): boolean => loading],
            noRecordings: [
                (s) => [s.volumeEstimate],
                (estimate: EstimateResponseApi | null): boolean =>
                    estimate !== null && estimate.matched_sessions_in_window === 0,
            ],
        }),

        afterMount(({ actions, values }) => {
            const cached = freshSnapshot(values.cachedSnapshot, values.currentTeamId)
            if (cached) {
                actions.loadVolumeEstimateSuccess(cached)
            } else {
                actions.loadVolumeEstimate()
            }
        }),
    ])
